    const int times[] = {
        0, 70, 140, 210, 280, 350, 601, 671, 741,
        811, 881, 951, 1202, 1272, 1342, 1412, 1440
    };

    char s[6];
    while (scanf("%5s", s) == 1) {
        int current = (s[0] - '0') * 600 +
                      (s[1] - '0') * 60 +
                      (s[3] - '0') * 10 +
                      (s[4] - '0');

        const int* next = std::lower_bound(times, times + 17, current);
        printf("%d\n", *next - current);
    }

    return 0;
}

